// src/services/MockBackend.js
class MockBackend {
  constructor() {
    this.rooms = new Map();
    this.listeners = new Map();
    this.setupStorageListener();
  }

  setupStorageListener() {
    // Listen for cross-tab events
    window.addEventListener('storage', (event) => {
      if (event.key && event.key.startsWith('mock-party-event-')) {
        try {
          const data = JSON.parse(event.newValue);
          this.processEvent(data);
        } catch (e) {
          console.error('Error parsing storage event:', e);
        }
      }
    });
  }

  // Broadcast event to all tabs
  broadcastEvent(eventData) {
    const key = `mock-party-event-${Date.now()}-${Math.random()}`;
    localStorage.setItem(key, JSON.stringify(eventData));
    // Clean up after 1 second
    setTimeout(() => localStorage.removeItem(key), 1000);
    
    // Also trigger locally
    this.processEvent(eventData);
  }

  processEvent(eventData) {
    const { roomId, eventType, payload, senderId } = eventData;
    const room = this.rooms.get(roomId);
    if (!room) return;
    
    const sender = room.participants.get(senderId);
    if (!sender) return;
    
    // Skip if sender is the one who triggered (for local)
    // But we want to process for others
    this.handleEvent(roomId, eventType, payload, senderId);
  }

  createRoom(roomId, hostId, hostUsername) {
    const room = {
      roomId,
      participants: new Map(),
      state: {
        videoId: 'dQw4w9WgXcQ',
        isPlaying: false,
        currentTime: 0,
        lastUpdated: Date.now()
      }
    };
    
    room.participants.set(hostId, {
      userId: hostId,
      username: hostUsername,
      role: 'HOST',
      joinedAt: new Date()
    });
    
    this.rooms.set(roomId, room);
    this.saveRoomToStorage(roomId);
    
    return room;
  }

  joinRoom(roomId, userId, username) {
    const room = this.rooms.get(roomId);
    if (!room) return null;
    
    if (!room.participants.has(userId)) {
      room.participants.set(userId, {
        userId,
        username,
        role: 'PARTICIPANT',
        joinedAt: new Date()
      });
      
      // Broadcast user joined
      this.broadcastEvent({
        roomId,
        eventType: 'user_joined',
        payload: { userId, username, role: 'PARTICIPANT' },
        senderId: userId
      });
      
      this.saveRoomToStorage(roomId);
    }
    
    return {
      roomId,
      userId,
      role: room.participants.get(userId).role,
      state: room.state
    };
  }

  handleEvent(roomId, eventType, payload, senderId) {
    const room = this.rooms.get(roomId);
    if (!room) return;
    
    const sender = room.participants.get(senderId);
    if (!sender) return;
    
    switch(eventType) {
      case 'play':
        if (sender.role === 'HOST' || sender.role === 'MODERATOR') {
          room.state.isPlaying = true;
          this.notifyListeners(roomId, 'play', { currentTime: room.state.currentTime });
          this.saveRoomToStorage(roomId);
        }
        break;
        
      case 'pause':
        if (sender.role === 'HOST' || sender.role === 'MODERATOR') {
          room.state.isPlaying = false;
          this.notifyListeners(roomId, 'pause', { currentTime: room.state.currentTime });
          this.saveRoomToStorage(roomId);
        }
        break;
        
      case 'seek':
        if (sender.role === 'HOST' || sender.role === 'MODERATOR') {
          room.state.currentTime = payload.time;
          this.notifyListeners(roomId, 'seek', { time: payload.time });
          this.saveRoomToStorage(roomId);
        }
        break;
        
      case 'change_video':
        if (sender.role === 'HOST' || sender.role === 'MODERATOR') {
          room.state.videoId = payload.videoId;
          room.state.currentTime = 0;
          room.state.isPlaying = false;
          this.notifyListeners(roomId, 'change_video', { videoId: payload.videoId });
          this.saveRoomToStorage(roomId);
        }
        break;
        
      case 'assign_role':
        if (sender.role === 'HOST') {
          const target = room.participants.get(payload.targetId);
          if (target) {
            target.role = payload.role;
            this.notifyListeners(roomId, 'role_assigned', {
              userId: payload.targetId,
              role: payload.role
            });
            this.saveRoomToStorage(roomId);
          }
        }
        break;
        
      case 'remove_participant':
        if (sender.role === 'HOST') {
          room.participants.delete(payload.targetId);
          this.notifyListeners(roomId, 'participant_removed', {
            userId: payload.targetId
          });
          this.saveRoomToStorage(roomId);
        }
        break;
        
      case 'chat':
        this.notifyListeners(roomId, 'chat', {
          username: payload.username,
          message: payload.message
        });
        break;
        
      case 'leave_room':
        const leaver = room.participants.get(senderId);
        if (leaver) {
          room.participants.delete(senderId);
          this.notifyListeners(roomId, 'user_left', {
            userId: senderId,
            username: leaver.username
          });
          this.saveRoomToStorage(roomId);
        }
        break;
    }
  }

  notifyListeners(roomId, eventType, payload) {
    if (this.listeners.has(roomId)) {
      this.listeners.get(roomId).forEach(callback => {
        try {
          callback(eventType, payload);
        } catch (e) {
          console.error('Error in callback:', e);
        }
      });
    }
  }

  subscribe(roomId, callback) {
    if (!this.listeners.has(roomId)) {
      this.listeners.set(roomId, new Set());
    }
    this.listeners.get(roomId).add(callback);
    
    return () => {
      if (this.listeners.has(roomId)) {
        this.listeners.get(roomId).delete(callback);
      }
    };
  }

  saveRoomToStorage(roomId) {
    const room = this.rooms.get(roomId);
    if (room) {
      const serialized = {
        roomId: room.roomId,
        participants: Array.from(room.participants.entries()),
        state: room.state
      };
      localStorage.setItem(`mock-room-${roomId}`, JSON.stringify(serialized));
    }
  }

  getRoom(roomId) {
    return this.rooms.get(roomId);
  }

  getParticipants(roomId) {
    const room = this.rooms.get(roomId);
    return room ? Array.from(room.participants.values()) : [];
  }

  getRoomState(roomId) {
    const room = this.rooms.get(roomId);
    return room ? room.state : null;
  }
}

const mockBackend = new MockBackend();
export default mockBackend;
